INSERT INTO tensor_maturity_verdicts (repo, scope, mission_id, level, evidence, verdict_by)
VALUES ('TensorLBM', 'm17968 XVAL-LBM-INSTRUCTION-DSL-TESTS-SH', 18092, 4,
$ev${"summary": "m17968 指令 DSL：1010 行真实现（parse→build_scheme→run，矩空间碰撞+Strang半步力+半程反弹）；审计独立重算 Poiseuille 0.68559%/0.34831%（交付 0.686/0.348 吻合）、pylbm 对表 M/w 差 0.0 且与教科书权重一致、f_eq 1.11e-16；30 项 pytest 复跑通过、repro_cmd rc=0 30s 全判据 PASS。判 L4 基准验证级；L3 产线集成未达（无主求解器调用方）；F3 交付物全部 untracked 未入 commit（阻塞发货）；F1 二阶收敛表述过强（实测 p=1.670）；F2 TG ν 误差对拟合采样敏感（0.0132% vs 审计 0.0809%）。", "level": 4, "level_rubric": "L1 单元验证=过；L2 独立功能实现=过（真代码零 MOCK）；L3 系统集成=未达（全仓 grep 仅自身 benchmarks/tests 引用，__init__ 未导出）；L4 基准验证=过（2 类解析锚点×2 分辨率+逐项误差表+OSS 算子层对表+sha256+独立复跑）；L5 不宣称", "impl_files": ["/root/tp-agent/work/m17968/src/tensorlbm/instruction_dsl.py:328 parse() | :583 build_scheme() | :887 run() | :854 _stream_periodic | :862 _stream_channel | :133 _compile_expression(AST 白名单)", "/root/tp-agent/work/m17968/benchmarks/xval_instruction_dsl/run_xval.py:122 pylbm_reference | :247 run_case | :226 _parabola_fit", "/root/tp-agent/work/m17968/tests/test_instruction_dsl.py (275 lines, 30 cases)", "/root/tp-agent/work/m18092/artifacts/board_audit/m18092/independent_recompute.py (审计者自写，不 import 交付 KPI 函数)"], "entry": "tensorlbm.instruction_dsl: parse(text)->Program, build_scheme(prog)->Scheme, run(prog|str)->RunResult；驱动入口 python benchmarks/xval_instruction_dsl/run_xval.py", "run_artifacts": ["/root/tp-agent/work/m17968/artifacts/xval_instruction_dsl/results.json", "/root/tp-agent/work/m17968/artifacts/xval_instruction_dsl/summary.md", "/root/tp-agent/work/m17968/artifacts/xval_instruction_dsl/figures/poiseuille_taylor_green.png (85948 B)", "/root/tp-agent/work/m17968/artifacts/xval_instruction_dsl/programs/{scheme,poiseuille_ny22,poiseuille_ny32,taylor_green_32,taylor_green_64}.lbm", "/root/tp-agent/work/m18092/artifacts/board_audit/m18092/recompute.json", "/root/tp-agent/work/m18092/artifacts/board_audit/m18092/audit_recompute.png (152745 B)"], "tests": "/root/tp-agent/work/m17968/tests/test_instruction_dsl.py —— 审计复跑 python -m pytest tests/test_instruction_dsl.py -q => 30 passed, 1 warning in 11.32s", "integration_callers": "未达 L3：全仓 grep -rln instruction_dsl 仅命中自身 src/tensorlbm/instruction_dsl.py + benchmarks/xval_instruction_dsl/{run_xval,make_figures}.py + tests/test_instruction_dsl.py + docs/*.md；src/tensorlbm/__init__.py 未导出；无主求解器/CLI/平台 API 调用方", "benchmark": {"referee_row_at_delivery": "tensor_benchmark_cases WHERE anchor_slug='XVAL-LBM-INSTRUCTION-DSL-TESTS-SH' => 0 rows；server_quality_audit={gate_valid:false, gate_missing_warning:true}；本审计补注册 3 行 status=passed", "predeclared_criteria": "docs 头部先于计算声明：scheme 语义差 <=1e-12；物理锚点 <15%(owner)，更严 <3%", "pylbm_parity": "审计自建 dico（多项式/平衡态读自 programs/scheme.lbm 文本）复算：M max abs diff=0.0，权重 diff=0.0 且与教科书 D2Q9 (4/9,1/9x4,1/36x4) 一致，f_eq max abs diff=1.110e-16（8 组随机宏观态；交付 1.665e-16）=> <=1e-12 成立", "poiseuille": "解析抛物线 u=g(y-1/2)(ny-3/2-y)/(2nu)：审计重算 max_rel_error=0.68559%(ny22,12000步) / 0.34831%(ny32,30000步)（交付 0.686%/0.348% 吻合）；壁面实测 0.512/20.488、0.508/30.492（理论 0.5 与 ny-1.5）=> H=ny-2 成立", "taylor_green": "nu 拟合（ln A 线性，A=sqrt(2KE)）：审计 0.0809%(32^2)/0.1822%(64^2)，交付 0.0132%/0.1036%(sample_every=2)；均 <3% 但暴露拟合窗口敏感性", "convergence": "H=20->30 误差比 1.9683；二阶应 2.25；隐含阶 p=1.670 => 交付『二阶收敛』表述过强；<3% 判据不受影响", "verdict": "全部先于声明的判据成立（scheme<=1e-12 通过；物理锚点 worst 0.686% <3% <15%）"}, "repro_cmd": "cd /root/tp-agent/work/m17968 && python benchmarks/xval_instruction_dsl/run_xval.py  # 审计实跑 rc=0, 30 s, criteria 全 True；pytest -q => 30 passed 11.32s。注：该驱动默认原地重写 artifacts/xval_instruction_dsl/results.json（仅 generated_at/wall_time_s 变化，数值段逐位一致）", "external_anchor": "pylbm 0.12.0 @ /root/oss-cache/pylbm commit f9f5d1647ccc10aa2fc7a93690cc56450432ee24（pylbm/scheme.py:506 _create_moments_matrices、:238 _get_equilibrium、stencil.py:643、validator.py:187）；方法谱系 Krueger et al. 2017 ch.3/ch.5、Lallemand & Luo 2000 PRE 61,6546、Guo 2002 Chin.J.Phys. 40,1（二阶强迫）、Ziegler 1993（半程反弹 y=1/2）。限定：仅算子层对表，单进程离线垫片 tools/xval_pylbm_stub/mpi4py（no-op 非 MPI），未做整解场 parity", "findings": {"F3_blocking_shipment": "交付物全部 untracked：git status --porcelain = 6 行 '??'；git ls-files --error-unmatch src/tensorlbm/instruction_dsl.py => did not match any file(s) known to git；mission result head_commit=null/branch=null => 平台自动推送无从推起，main 与生态检出均无该模块", "F1_overclaim": "docs §5 比值 1.97 约等于 2.25 => 二阶收敛：实测隐含阶 p=1.670（差 12.5%），须改述并补第三分辨率", "F2_repro_gap": "TG nu 误差依赖拟合采样：sample_every=2 => 0.0132%，sample_every=1 => 0.0809%（6x）；results.json 未记录拟合窗口 => 三位有效数字不可独立复现（PASS 结论不变）", "F4_referee_absent": "交付时 tensor_benchmark_cases 本 anchor 0 行（gate_valid=false）=> 本审计补注册消解", "F5_scope_limit": "mpi4py 垫片为单进程 no-op，仅离线 import；引用须限定『算子层 parity，非整解场』", "F6_observation": "docs 指出既有 bitflag_d2q9.poiseuille_profile 用 H=ny-1 与自身 make_channel 几何不一致；本单未修，建议另立节点"}, "checks_run": "工件实存 ls/stat；源码逐段读判 REAL vs MOCK/STUB（parse/build_scheme/run 主体 + 流核）；repro_cmd 实跑 rc=0；pytest 30 项复跑；独立重算脚本（自写解析抛物线 + 自写 ln A 拟合 + pylbm 自建 dico 复算）对拍交付数字；SQL 核 tensor_benchmark_cases / tensor_xval_cases / tensor_reports(16892) / tensor_dev_missions(17968)；git status + ls-files 核 commit 状态", "checks_not_run": "pylbm 整解场 parity（只比算子层）；第三分辨率 H=45/N=128^2 收敛阶验证；集群 loong64 复跑（30 s 级未占集群）；TCLB 二进制 parity（非本 anchor 主题）", "report_six_sections": "docs/XVAL-LBM-INSTRUCTION-DSL-TESTS-SH.md ①-⑥ 齐；平台报告 tensor_reports id=16892 mission_id=17968 实存；本审计另有 docs/board_audit/m18092/audit_m17968.md + 图 artifacts/board_audit/m18092/audit_recompute.png", "disposition": "approve with notes — L4（基准验证级）；confirmed 语义=基准与能力成立；发货资格另需 F3(commit/合入 main) + F1/F2 收口"}$ev$, 'board-audit')
ON CONFLICT (repo, scope, verdict_by) DO UPDATE SET mission_id=EXCLUDED.mission_id, level=EXCLUDED.level, evidence=EXCLUDED.evidence;

